package com.nexamart.backend.repository;import com.nexamart.backend.domain.Product;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface ProductRepository extends JpaRepository<Product,Long>{@Query("select p from Product p where (:q is null or lower(p.name) like lower(concat('%',:q,'%')) or lower(coalesce(p.sku,'')) like lower(concat('%',:q,'%'))) and (:active is null or p.available=:active) and (:categoryId is null or p.category.id=:categoryId)")Page<Product> search(@Param("q")String q,@Param("active")Boolean active,@Param("categoryId")Long categoryId,Pageable p);}
